local _,F=...
-- Build location/search metadata only from the Classic ability-source rows.
F.classicCreatures={}
for _,ability in ipairs(F.petBrowserAbilities) do
    for _,rank in ipairs(ability.ranks) do
        for _,animal in ipairs(rank.animals) do
            local row=F.classicCreatures[animal.id]
            if not row then
                row={name=animal.name,family=animal.family,zone=animal.zone}
                local low,high=animal.levels:match('^(%d+)%-(%d+)$')
                low=tonumber(low or animal.levels);high=tonumber(high) or low
                row.minLevel=low;row.maxLevel=high
                F.classicCreatures[animal.id]=row
            end
        end
    end
end
F.petDatabaseSource='Petopia Classic; live Beast Lore and observed tames take priority.'

